19	<style>
20	:root{--navy:#040038;--electric:#001AFF;--lightblue:#5D8FFF;--blue100:#DDE8FF;--blue200:#BFD5FF}
21	*{box-sizing:border-box}
22	body{margin:0;background:var(--navy);color:#fff;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Tahoma,sans-serif;-webkit-font-smoothing:antialiased}
23	body{display:grid;grid-template-columns:230px minmax(0,1fr)}
24	aside{position:sticky;top:0;height:100vh;overflow-y:auto;padding:40px 0 40px 28px;
25	border-right:1px solid rgba(255,255,255,.12)}
26	.brand{display:flex;align-items:center;gap:9px;margin:0 0 36px;font-size:13px;font-weight:600;
27	letter-spacing:2px;text-transform:uppercase;color:var(--lightblue)}
28	.brand img{width:18px;height:18px}
29	aside nav{display:flex;flex-direction:column;gap:2px;padding:0}
30	aside nav a{display:flex;align-items:center;justify-content:space-between;gap:10px;
31	min-height:38px;padding:0 16px 0 12px;border:0;border-left:2px solid transparent;
32	color:var(--blue100);opacity:.72;text-decoration:none;font-size:14px;
33	transition:opacity .18s,border-color .18s,background .18s}
34	aside nav a:hover{opacity:1;background:rgba(255,255,255,.05)}
35	aside nav a.on{opacity:1;border-left-color:var(--electric);background:rgba(255,255,255,.05)}
36	aside nav a .n{font-size:12px;opacity:.55;font-variant-numeric:tabular-nums}
37	.navsep{margin:20px 12px 10px;font-size:11px;letter-spacing:1.6px;text-transform:uppercase;
38	color:var(--blue200);opacity:.45}
39	main{min-width:0}
40	header{padding:clamp(48px,9vw,120px) clamp(24px,5vw,64px) 56px;max-width:1200px}
41	@media(max-width:900px){
42	  body{grid-template-columns:1fr}
43	  aside{position:static;height:auto;border-right:0;border-bottom:1px solid rgba(255,255,255,.12);
44	  padding:24px 24px 20px}
45	  .brand{margin-bottom:18px}
46	  aside nav{flex-direction:row;flex-wrap:wrap;gap:8px}
47	  aside nav a{border-left:0;border:1px solid rgba(255,255,255,.18);padding:0 14px;min-height:44px}
48	  aside nav a.on{border-color:var(--electric);border-left-width:1px}
49	  .navsep{display:none}
50	}
51	.eyebrow{color:var(--lightblue);text-transform:uppercase;letter-spacing:2.4px;font-size:14px;font-weight:600;margin:0 0 28px}
52	h1{font-family:Georgia,'Times New Roman',serif;font-size:clamp(44px,7vw,96px);font-weight:400;letter-spacing:-2px;line-height:1.02;margin:0 0 28px}
53	.lede{color:var(--blue100);font-size:clamp(17px,2vw,21px);line-height:1.65;max-width:62ch;margin:0 0 12px;opacity:.88}
54	.meta{color:var(--blue200);opacity:.7;font-size:15px;margin:24px 0 0;font-variant-numeric:tabular-nums}
55	section{padding:0 clamp(24px,5vw,64px)}
56	.tagbar{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 34px}
57	.tagbar button{min-height:32px;padding:0 12px;background:transparent;color:var(--blue100);
58	border:1px solid rgba(255,255,255,.18);font:inherit;font-size:12.5px;cursor:pointer;opacity:.8;
59	transition:opacity .18s,border-color .18s,background .18s}
60	.tagbar button:hover{opacity:1;border-color:var(--lightblue)}
61	.tagbar button[aria-pressed="true"]{background:var(--electric);border-color:var(--electric);color:#fff;opacity:1}
62	.tags{display:flex;flex-wrap:wrap;gap:5px;padding-top:7px}
63	.tags span{font-size:11px;letter-spacing:.3px;color:var(--blue200);opacity:.62;
64	border:1px solid rgba(255,255,255,.14);padding:2px 7px}
65	figure[hidden]{display:none}
66	.empty{color:var(--blue200);opacity:.6;font-size:15px;padding:12px 0 24px}
67	h2{font-family:Georgia,serif;font-weight:500;font-size:clamp(28px,3.4vw,40px);margin:72px 0 6px;border-top:1px solid rgba(255,255,255,.14);padding-top:28px;letter-spacing:-.5px}
68	.sub{color:var(--blue200);opacity:.7;font-size:15px;margin:0 0 28px;max-width:60ch;line-height:1.6}
69	.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:24px}
70	figure{margin:0}
71	.shot{position:relative;display:block;line-height:0}
72	a.card{display:block;text-decoration:none;color:inherit}
73	img{width:100%;aspect-ratio:16/10;object-fit:cover;display:block;background:#01006E;transition:opacity .15s}
74	a.card:hover img{opacity:.82}
75	.dl{position:absolute;top:10px;right:10px;display:inline-flex;align-items:center;gap:6px;
76	padding:7px 12px;background:rgba(4,0,56,.82);color:#fff;border:1px solid rgba(255,255,255,.28);
77	font-size:12px;line-height:1;text-decoration:none;letter-spacing:.4px;
78	opacity:0;transform:translateY(-4px);transition:opacity .15s,transform .15s,background .15s;
79	backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
80	.shot:hover .dl,.dl:focus{opacity:1;transform:translateY(0)}
81	.dl:hover{background:var(--electric);border-color:var(--electric)}
82	.dl svg{width:13px;height:13px;flex:none}
83	@media (hover:none){.dl{opacity:1;transform:none}}
84	figcaption{display:flex;justify-content:space-between;align-items:center;gap:10px;padding-top:10px;font-size:12.5px;color:var(--blue200);opacity:.72;font-variant-numeric:tabular-nums}
85	.sw{width:11px;height:11px;display:inline-block;margin-right:6px;vertical-align:-1px;border:1px solid rgba(255,255,255,.25)}
86	footer{margin-top:88px;padding:56px clamp(24px,5vw,80px) 72px;border-top:1px solid rgba(255,255,255,.14);color:var(--blue200);font-size:15px;line-height:1.8;opacity:.75}
87	code{background:rgba(255,255,255,.08);padding:3px 8px;font-size:13px;white-space:nowrap}
88	footer code{white-space:normal;word-break:break-all}
89	a.link{color:var(--lightblue)}
90	#recolor .sub{max-width:none}
91	.pgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:24px}
92	.pcard{border:1px solid rgba(255,255,255,.14);padding:20px;display:flex;flex-direction:column;gap:14px;background:rgba(255,255,255,.02)}
93	.phead{display:flex;align-items:center;justify-content:space-between;gap:12px}
94	.pname{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:600;letter-spacing:.2px}
95	.pdot{width:14px;height:14px;flex:none;border:1px solid rgba(255,255,255,.3)}
96	.psum{color:var(--blue200);opacity:.66;font-size:13px;margin:-6px 0 0}
97	.ptext{color:var(--blue100);opacity:.82;font-size:13.5px;line-height:1.65;max-height:150px;overflow-y:auto;
98	padding-right:10px;white-space:pre-wrap;border-left:1px solid rgba(255,255,255,.14);padding-left:14px}
99	.ptext::-webkit-scrollbar{width:5px}
100	.ptext::-webkit-scrollbar-thumb{background:rgba(255,255,255,.2)}

